/// Metadata about a chunk's position in the original document.
public struct ChunkMetadata: Codable, Sendable, Hashable {
    /// Byte offset where this chunk starts in the original text (UTF-8 valid boundary).
    public let byteStart: UInt
    /// Byte offset where this chunk ends in the original text (UTF-8 valid boundary).
    public let byteEnd: UInt
    /// Number of tokens in this chunk (if available).
    ///
    /// This is calculated by the embedding model's tokenizer if embeddings are enabled.
    public let tokenCount: UInt?
    /// Zero-based index of this chunk in the document.
    public let chunkIndex: UInt
    /// Total number of chunks in the document.
    public let totalChunks: UInt
    /// First page number this chunk spans (1-indexed).
    ///
    /// Only populated when page tracking is enabled in extraction configuration.
    public let firstPage: UInt32?
    /// Last page number this chunk spans (1-indexed, equal to first_page for single-page chunks).
    ///
    /// Only populated when page tracking is enabled in extraction configuration.
    public let lastPage: UInt32?
    /// Heading context when using Markdown chunker.
    ///
    /// Contains the heading hierarchy this chunk falls under.
    /// Only populated when `ChunkerType::Markdown` is used.
    public let headingContext: HeadingContext?
    /// Flattened heading trail from document root to this chunk's section.
    ///
    /// Each element is a heading's text, outermost first. Derived from
    /// [`heading_context`](Self::heading_context) when present; empty otherwise.
    /// Provides a binding-friendly, RAG-shaped breadcrumb without requiring
    /// callers to walk the nested [`HeadingContext`] structure.
    public let headingPath: [String]
    /// Indices into `ExtractedDocument.images` for images on pages covered by this chunk.
    ///
    /// Contains zero-based indices into the top-level `images` collection for every
    /// image whose `page_number` falls within `[first_page, last_page]`.
    /// Empty when image extraction is disabled or the chunk spans no pages with images.
    public let imageIndices: [UInt32]
    /// Ids of the [`DocumentNode`](super::document_structure::DocumentNode)s
    /// this chunk was derived from.
    ///
    /// Joins a chunk back to the structured document tree via
    /// [`DocumentNode::id`](super::document_structure::DocumentNode::id).
    /// Populated from exact node provenance when available, with a textual
    /// containment fallback for rendered chunks that do not retain byte offsets.
    public let nodeIds: [String]
    /// Per-page bounding-box spans this chunk covers, for viewer highlighting (#1295).
    ///
    /// One entry per page the chunk overlaps, in page order — the first and last entries'
    /// `page` fields equal [`first_page`](Self::first_page)/[`last_page`](Self::last_page).
    /// Populated whenever page-boundary provenance is available (the same condition under
    /// which `first_page`/`last_page` are populated); each entry's `bbox` is additionally
    /// populated when the document's structured node tree ([`ExtractedDocument::document`]) is
    /// available, as the union of that page's body-layer node bounding boxes found within this
    /// chunk. Empty when page-boundary provenance is unavailable (mirrors `first_page`/
    /// `last_page` being `None`).
    public let pageSpans: [PageSpan]
    /// Multi-label classification result for this chunk.
    ///
    /// Populated by the chunk-classification post-processor when
    /// [`ExtractionConfig::chunk_classification`](crate::core::config::ExtractionConfig::chunk_classification)
    /// is set. A chunk may match zero, one, or many of the configured label
    /// definitions. Empty when chunk classification was not configured.
    public let classifications: [ClassificationLabel]
    public init(byteStart: UInt, byteEnd: UInt, tokenCount: UInt? = nil, chunkIndex: UInt, totalChunks: UInt, firstPage: UInt32? = nil, lastPage: UInt32? = nil, headingContext: HeadingContext? = nil, headingPath: [String] = [], imageIndices: [UInt32] = [], nodeIds: [String] = [], pageSpans: [PageSpan] = [], classifications: [ClassificationLabel] = []) {
        self.byteStart = byteStart
        self.byteEnd = byteEnd
        self.tokenCount = tokenCount
        self.chunkIndex = chunkIndex
        self.totalChunks = totalChunks
        self.firstPage = firstPage
        self.lastPage = lastPage
        self.headingContext = headingContext
        self.headingPath = headingPath
        self.imageIndices = imageIndices
        self.nodeIds = nodeIds
        self.pageSpans = pageSpans
        self.classifications = classifications
    }
    private enum CodingKeys: String, CodingKey {
        case byteStart = "byte_start"
        case byteEnd = "byte_end"
        case tokenCount = "token_count"
        case chunkIndex = "chunk_index"
        case totalChunks = "total_chunks"
        case firstPage = "first_page"
        case lastPage = "last_page"
        case headingContext = "heading_context"
        case headingPath = "heading_path"
        case imageIndices = "image_indices"
        case nodeIds = "node_ids"
        case pageSpans = "page_spans"
        case classifications = "classifications"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.byteStart = try container.decode(UInt.self, forKey: .byteStart)
        self.byteEnd = try container.decode(UInt.self, forKey: .byteEnd)
        self.tokenCount = try container.decodeIfPresent(UInt.self, forKey: .tokenCount) ?? nil
        self.chunkIndex = try container.decode(UInt.self, forKey: .chunkIndex)
        self.totalChunks = try container.decode(UInt.self, forKey: .totalChunks)
        self.firstPage = try container.decodeIfPresent(UInt32.self, forKey: .firstPage) ?? nil
        self.lastPage = try container.decodeIfPresent(UInt32.self, forKey: .lastPage) ?? nil
        self.headingContext = try container.decodeIfPresent(HeadingContext.self, forKey: .headingContext) ?? nil
        if container.contains(.headingPath) {
            self.headingPath = try container.decode([String].self, forKey: .headingPath)
        } else {
            self.headingPath = []
        }
        if container.contains(.imageIndices) {
            self.imageIndices = try container.decode([UInt32].self, forKey: .imageIndices)
        } else {
            self.imageIndices = []
        }
        if container.contains(.nodeIds) {
            self.nodeIds = try container.decode([String].self, forKey: .nodeIds)
        } else {
            self.nodeIds = []
        }
        if container.contains(.pageSpans) {
            self.pageSpans = try container.decode([PageSpan].self, forKey: .pageSpans)
        } else {
            self.pageSpans = []
        }
        if container.contains(.classifications) {
            self.classifications = try container.decode([ClassificationLabel].self, forKey: .classifications)
        } else {
            self.classifications = []
        }
    }
}

