/// Controls thread usage for constrained environments.
///
/// Set `max_threads` to cap all internal thread pools (Rayon, ONNX Runtime
/// intra-op), batch concurrency and Tesseract recognition to a single limit.
/// Set `max_concurrent_ocr` to give recognition a limit of its own, which is
/// the knob to reach for when the host has cores to spare but not the memory
/// to run a recognition session on each of them. It is applied as given and
/// is not capped by `max_threads`. The first extraction in a process fixes
/// it for that process — see the field's own documentation.
///
/// # Default budget when `max_threads` is unset
///
/// Without an explicit `max_threads`, the effective budget is
/// `min(detected_cpu_cores, 8)` — a deliberate ceiling chosen for
/// serverless/shared-tenant defaults, not a full-host auto-scale. On a host
/// with more than 8 cores this means the extra cores go **unused** unless one
/// of the following applies:
///
/// - `max_threads` is set explicitly above 8 (the only way to exceed the
///   ceiling on a bare-metal or VM host with no CPU quota).
/// - The process runs under a Linux cgroup CPU quota (containers, Kubernetes
///   `resources.limits.cpu`); in that case the quota itself is used as the
///   ceiling instead of the hardcoded 8, since the quota already reflects a
///   deliberately-configured resource limit.
///
/// When neither applies and the host has more than 8 cores, a single
/// `WARN`-level log is emitted the first time the budget is resolved,
/// naming the detected core count and the applied cap, so the ceiling is
/// discoverable without reading source.
///
/// # Example
///
/// ```rust
/// use xberg::core::config::ConcurrencyConfig;
///
/// let config = ConcurrencyConfig {
///     max_threads: Some(2),
///     max_concurrent_ocr: None,
/// };
/// ```
public struct ConcurrencyConfig: Codable, Sendable, Hashable {
    /// Maximum number of threads for all internal thread pools.
    ///
    /// Caps Rayon global pool size, ONNX Runtime intra-op threads, and the
    /// combined document/inner-task budget for batch extraction. When `None`,
    /// the effective budget is `min(detected_cpu_cores, 8)` unless a Linux
    /// cgroup CPU quota is present, in which case the quota is used as the
    /// ceiling instead. On hosts with more than 8 cores and no cgroup quota,
    /// set `max_threads` explicitly to use the additional cores — the
    /// default will not scale past 8 on its own.
    public let maxThreads: UInt?
    /// Maximum number of Tesseract recognition sessions that run at once.
    ///
    /// When `None`, recognition follows `max_threads`, reduced to the number
    /// of sessions the host's free memory holds. Each session keeps its own
    /// page image and recognition working set resident, so a host with many
    /// cores and little memory needs this lower than the thread budget. Set
    /// it to `4` to keep the fixed limit that releases up to 1.2.6 applied.
    ///
    /// A value set here is applied as given: neither the thread budget nor
    /// the memory reading reduces it. Both of those bound the automatic
    /// limit, and a caller who names a number has already decided what the
    /// host can carry.
    ///
    /// The first extraction in a process fixes the limit for the rest of that
    /// process, and a later extraction that names a different value keeps the
    /// first one. The two limiters that enforce it — the admission semaphore
    /// in the Tesseract backend and the handle pool behind it — are built once
    /// inside a backend the plugin registry holds for the life of the process,
    /// and the pool's capacity is fixed when it is constructed. A later value
    /// could therefore be reported but never enforced. Set it on the first
    /// extraction, or run one process per value.
    public let maxConcurrentOcr: UInt?
    public init(maxThreads: UInt? = nil, maxConcurrentOcr: UInt? = nil) {
        self.maxThreads = maxThreads
        self.maxConcurrentOcr = maxConcurrentOcr
    }
    private enum CodingKeys: String, CodingKey {
        case maxThreads = "max_threads"
        case maxConcurrentOcr = "max_concurrent_ocr"
    }
    private struct AlefWireKey: CodingKey {
        let stringValue: String
        var intValue: Int? { nil }
        init?(stringValue: String) { self.stringValue = stringValue }
        init?(intValue: Int) { return nil }
    }
    public init(from decoder: any Decoder) throws {
        let allFields = try decoder.container(keyedBy: AlefWireKey.self)
        if let key = allFields.allKeys.first(where: { CodingKeys(rawValue: $0.stringValue) == nil }) {
            throw DecodingError.dataCorruptedError(forKey: key, in: allFields, debugDescription: "Unknown field")
        }
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.maxThreads = try container.decodeIfPresent(UInt.self, forKey: .maxThreads) ?? nil
        self.maxConcurrentOcr = try container.decodeIfPresent(UInt.self, forKey: .maxConcurrentOcr) ?? nil
    }
}

// MARK: - Internal FFI conversions for ConcurrencyConfig
internal extension ConcurrencyConfig {
    init(_ rb: RustBridge.ConcurrencyConfigRef) throws {
        self.maxThreads = rb.maxThreads()
        self.maxConcurrentOcr = rb.maxConcurrentOcr()
    }

    func intoRust() throws -> RustBridge.ConcurrencyConfig {
        return RustBridge.ConcurrencyConfig(self.maxThreads, self.maxConcurrentOcr)
    }
}

/// Cross-extractor content filtering configuration.
///
/// Controls whether "furniture" content (headers, footers, page numbers,
/// watermarks, repeating text) is included in or stripped from extraction
/// results. Applies across all extractors (PDF, DOCX, RTF, ODT, HTML, etc.)
/// with format-specific implementation.
///
/// When `None` on `ExtractionConfig`, each extractor uses its current
/// default behavior unchanged.
public struct ContentFilterConfig: Codable, Sendable, Hashable {
    /// Include running headers in extraction output.
    ///
    /// - PDF: Disables top-margin furniture stripping and prevents the layout
    ///   model from treating `PageHeader`-classified regions as furniture.
    /// - DOC/DOCX: Includes document headers in text output.
    /// - RTF/ODT: Headers already included; this is a no-op when true.
    /// - HTML/EPUB: Keeps `<header>` element content.
    ///
    /// Default: `false` (headers are stripped or excluded).
    public let includeHeaders: Bool
    /// Include running footers in extraction output.
    ///
    /// - PDF: Disables bottom-margin furniture stripping and prevents the layout
    ///   model from treating `PageFooter`-classified regions as furniture.
    /// - DOC/DOCX: Includes document footers in text output.
    /// - RTF/ODT: Footers already included; this is a no-op when true.
    /// - HTML/EPUB: Keeps `<footer>` element content.
    ///
    /// Default: `false` (footers are stripped or excluded).
    public let includeFooters: Bool
    /// Include footnote bodies in extraction output.
    ///
    /// - PDF: Prevents the layout model from treating `Footnote`-classified
    ///   regions as furniture, so footnote bodies survive alongside the main
    ///   text instead of being silently dropped.
    /// - DOC: Includes footnote definitions in extracted output.
    /// - Other formats: No effect currently.
    ///
    /// Default: `false` (footnotes are stripped), matching the existing
    /// `include_headers` / `include_footers` defaults.
    public let includeFootnotes: Bool
    /// Enable the heuristic cross-page repeating text detector.
    ///
    /// When `true` (default), text that repeats verbatim across a supermajority
    /// of pages is classified as furniture and stripped.  Disable this if brand
    /// names or repeated headings are being incorrectly removed by the heuristic.
    ///
    /// This flag also gates a same-page rule: a body paragraph is removed when
    /// its text is also carried by a table detected on the same page (catches
    /// table content that PDF extraction renders both as a table and as body
    /// text). The comparison preserves case and never touches headings, list
    /// items, code blocks, formulas, or captions, so it cannot delete a body
    /// sentence merely for repeating an earlier heading's words (GH#1623).
    ///
    /// Note: when a layout-detection model is active, the model may independently
    /// classify page-header / page-footer / footnote regions as furniture on a
    /// per-page basis. To preserve those regions, set `include_headers = true`,
    /// `include_footers = true`, `include_footnotes = true`, or any combination,
    /// in addition to disabling this flag.
    ///
    /// Primarily affects PDF extraction.
    ///
    /// Default: `true`.
    public let stripRepeatingText: Bool
    /// Include watermark text in extraction output.
    ///
    /// - PDF: Keeps watermark artifacts and arXiv identifiers.
    /// - Other formats: No effect currently.
    ///
    /// Default: `false` (watermarks are stripped).
    public let includeWatermarks: Bool
    public init(includeHeaders: Bool = false, includeFooters: Bool = false, includeFootnotes: Bool = false, stripRepeatingText: Bool = true, includeWatermarks: Bool = false) {
        self.includeHeaders = includeHeaders
        self.includeFooters = includeFooters
        self.includeFootnotes = includeFootnotes
        self.stripRepeatingText = stripRepeatingText
        self.includeWatermarks = includeWatermarks
    }
    private enum CodingKeys: String, CodingKey {
        case includeHeaders = "include_headers"
        case includeFooters = "include_footers"
        case includeFootnotes = "include_footnotes"
        case stripRepeatingText = "strip_repeating_text"
        case includeWatermarks = "include_watermarks"
    }
    private struct AlefWireKey: CodingKey {
        let stringValue: String
        var intValue: Int? { nil }
        init?(stringValue: String) { self.stringValue = stringValue }
        init?(intValue: Int) { return nil }
    }
    public init(from decoder: any Decoder) throws {
        let allFields = try decoder.container(keyedBy: AlefWireKey.self)
        if let key = allFields.allKeys.first(where: { CodingKeys(rawValue: $0.stringValue) == nil }) {
            throw DecodingError.dataCorruptedError(forKey: key, in: allFields, debugDescription: "Unknown field")
        }
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if container.contains(.includeHeaders) {
            self.includeHeaders = try container.decode(Bool.self, forKey: .includeHeaders)
        } else {
            self.includeHeaders = false
        }
        if container.contains(.includeFooters) {
            self.includeFooters = try container.decode(Bool.self, forKey: .includeFooters)
        } else {
            self.includeFooters = false
        }
        if container.contains(.includeFootnotes) {
            self.includeFootnotes = try container.decode(Bool.self, forKey: .includeFootnotes)
        } else {
            self.includeFootnotes = false
        }
        if container.contains(.stripRepeatingText) {
            self.stripRepeatingText = try container.decode(Bool.self, forKey: .stripRepeatingText)
        } else {
            self.stripRepeatingText = true
        }
        if container.contains(.includeWatermarks) {
            self.includeWatermarks = try container.decode(Bool.self, forKey: .includeWatermarks)
        } else {
            self.includeWatermarks = false
        }
    }
}

// MARK: - Internal FFI conversions for ContentFilterConfig
internal extension ContentFilterConfig {
    init(_ rb: RustBridge.ContentFilterConfigRef) throws {
        self.includeHeaders = rb.includeHeaders()
        self.includeFooters = rb.includeFooters()
        self.includeFootnotes = rb.includeFootnotes()
        self.stripRepeatingText = rb.stripRepeatingText()
