    /// Total number of data records in the DBF file.
    public let recordCount: UInt
    /// Number of field (column) definitions.
    public let fieldCount: UInt
    /// Descriptor for each field in the table schema.
    public let fields: [DbfFieldInfo]
    public init(recordCount: UInt, fieldCount: UInt, fields: [DbfFieldInfo] = []) {
        self.recordCount = recordCount
        self.fieldCount = fieldCount
        self.fields = fields
    }
    private enum CodingKeys: String, CodingKey {
        case recordCount = "record_count"
        case fieldCount = "field_count"
        case fields = "fields"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if container.contains(.recordCount) {
            self.recordCount = try container.decode(UInt.self, forKey: .recordCount)
        } else {
            self.recordCount = 0
        }
        if container.contains(.fieldCount) {
            self.fieldCount = try container.decode(UInt.self, forKey: .fieldCount)
        } else {
            self.fieldCount = 0
        }
        if container.contains(.fields) {
            self.fields = try container.decode([DbfFieldInfo].self, forKey: .fields)
        } else {
            self.fields = []
        }
    }
}

// MARK: - Internal FFI conversions for DbfMetadata
internal extension DbfMetadata {
    init(_ rb: RustBridge.DbfMetadataRef) throws {
        self.recordCount = rb.recordCount()
        self.fieldCount = rb.fieldCount()
        self.fields = try rb.fields().map { (s: RustStringRef) -> DbfFieldInfo in let d = s.as_str().toString().data(using: .utf8) ?? Data(); return try JSONDecoder().decode(DbfFieldInfo.self, from: d) }
    }

    func intoRust() throws -> RustBridge.DbfMetadata {
        let __fields = RustVec<RustBridge.DbfFieldInfo>()
        for __elem in self.fields { __fields.push(value: try __elem.intoRust()) }
        return RustBridge.DbfMetadata(self.recordCount, self.fieldCount, __fields)
    }
}

