/// Cheap structural counts for an extracted document.
///
/// Populated on every [`ExtractedDocument`] returned by `extract` /
/// `extract_batch`, regardless of whether the heavy `pages` / `images`
/// collections are materialized. A caller that only needs "how many pages /
/// tables / images did this document have?" (reporting, cost estimation,
/// progress, quotas) can read these without enabling per-page or per-image
/// extraction.
///
/// The page count comes from the parse (the extractor already walks the page
/// tree); it does not require opting into per-page content. `pages` is `0` for
/// inputs that are not page-addressable (e.g. plain text).
public struct DocumentCounts: Codable, Sendable, Hashable {
    /// Total pages in the source document (`0` when not page-addressable).
    public let pages: UInt
    /// Tables detected in the document.
    public let tables: UInt
    /// Images detected in the document.
    public let images: UInt
    public init(pages: UInt, tables: UInt, images: UInt) {
        self.pages = pages
        self.tables = tables
        self.images = images
    }
    private enum CodingKeys: String, CodingKey {
        case pages = "pages"
        case tables = "tables"
        case images = "images"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if container.contains(.pages) {
            self.pages = try container.decode(UInt.self, forKey: .pages)
        } else {
            self.pages = 0
        }
        if container.contains(.tables) {
            self.tables = try container.decode(UInt.self, forKey: .tables)
        } else {
            self.tables = 0
        }
        if container.contains(.images) {
            self.images = try container.decode(UInt.self, forKey: .images)
        } else {
            self.images = 0
        }
    }
}

// MARK: - Internal FFI conversions for DocumentCounts
internal extension DocumentCounts {
    init(_ rb: RustBridge.DocumentCountsRef) throws {
        self.pages = rb.pages()
        self.tables = rb.tables()
        self.images = rb.images()
    }

    func intoRust() throws -> RustBridge.DocumentCounts {
        return RustBridge.DocumentCounts(self.pages, self.tables, self.images)
    }
}

/// A single node in the document tree.
///
/// Each node has deterministic `id`, typed `content`, optional `parent`/`children`
/// for tree structure, and metadata like page number, bounding box, and content layer.
public struct DocumentNode: Codable, Sendable, Hashable {
    /// Deterministic identifier (hash of node type + text + page + position).
    ///
    /// Stable and unique within a single extraction response: every internal
    /// construction path threads the node's position (its index in
    /// `DocumentStructure::nodes`) into the hash, so identical
    /// `(node_type, text, page)` tuples at different positions never collide.
    /// Always serialised — `ChunkMetadata::node_ids` references it to join
    /// chunks back to the nodes they were derived from.
    /// `#[serde(default)]` covers the missing-field case on inbound JSON
    /// (e.g. documents serialised before this field existed).
    public let id: String
    /// Node content — tagged enum, type-specific data only.
    public let content: NodeContent
    /// Parent node index (`None` = root-level node).
    public let parent: UInt32?
    /// Child node indices in reading order.
    public let children: [UInt32]
    /// Content layer classification.
    ///
    /// Always serialised — Kotlin-Android (and any other typed binding) treats
    /// the field as non-nullable, so omitting it from the JSON wire would
    /// break consumer deserialisation.  `#[serde(default)]` covers the
    /// missing-field case on inbound JSON.
    public let contentLayer: ContentLayer
    /// Page number where this node starts (1-indexed).
    public let page: UInt32?
    /// Page number where this node ends (for multi-page tables/sections).
    public let pageEnd: UInt32?
    /// Bounding box in document coordinates.
    public let bbox: BoundingBox?
    /// Inline annotations (formatting, links) on this node's text content.
    ///
    /// Only meaningful for text-carrying nodes; empty for containers.
    public let annotations: [TextAnnotation]
    /// Format-specific key-value attributes.
    ///
    /// Extensible bag for miscellaneous data without a dedicated typed field: CSS classes,
    /// LaTeX environment names, Excel cell formulas, slide layout names, etc.
    public let attributes: [String: String]?
    public init(id: String, content: NodeContent, parent: UInt32? = nil, children: [UInt32] = [], contentLayer: ContentLayer, page: UInt32? = nil, pageEnd: UInt32? = nil, bbox: BoundingBox? = nil, annotations: [TextAnnotation] = [], attributes: [String: String]? = nil) {
        self.id = id
        self.content = content
        self.parent = parent
        self.children = children
        self.contentLayer = contentLayer
        self.page = page
        self.pageEnd = pageEnd
        self.bbox = bbox
        self.annotations = annotations
        self.attributes = attributes
    }
    private enum CodingKeys: String, CodingKey {
        case id = "id"
        case content = "content"
        case parent = "parent"
        case children = "children"
        case contentLayer = "content_layer"
        case page = "page"
        case pageEnd = "page_end"
        case bbox = "bbox"
        case annotations = "annotations"
        case attributes = "attributes"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if container.contains(.id) {
            self.id = try container.decode(String.self, forKey: .id)
        } else {
            self.id = ""
        }
        self.content = try container.decode(NodeContent.self, forKey: .content)
        self.parent = try container.decodeIfPresent(UInt32.self, forKey: .parent) ?? nil
        if container.contains(.children) {
            self.children = try container.decode([UInt32].self, forKey: .children)
        } else {
            self.children = []
        }
        self.contentLayer = try container.decode(ContentLayer.self, forKey: .contentLayer)
        self.page = try container.decodeIfPresent(UInt32.self, forKey: .page) ?? nil
        self.pageEnd = try container.decodeIfPresent(UInt32.self, forKey: .pageEnd) ?? nil
        self.bbox = try container.decodeIfPresent(BoundingBox.self, forKey: .bbox) ?? nil
        if container.contains(.annotations) {
            self.annotations = try container.decode([TextAnnotation].self, forKey: .annotations)
        } else {
            self.annotations = []
        }
        self.attributes = try container.decodeIfPresent([String: String].self, forKey: .attributes) ?? nil
    }
}

// MARK: - Internal FFI conversions for DocumentNode
internal extension DocumentNode {
    init(_ rb: RustBridge.DocumentNodeRef) throws {
        self.id = rb.id().toString()
        self.content = try JSONDecoder().decode(NodeContent.self, from: ((rb.content().toString()).data(using: .utf8) ?? Data("null".utf8)))
        self.parent = rb.parent()
        self.children = Array(rb.children())
        self.contentLayer = try { let rawValue = rb.contentLayer().toString(); guard let value = ContentLayer(rawValue: rawValue) else { throw JobError.validation(message: "Unknown ContentLayer variant", source: rawValue) }; return value }()
        self.page = rb.page()
        self.pageEnd = rb.pageEnd()
        self.bbox = try rb.bbox().map { try BoundingBox($0) }
        self.annotations = try rb.annotations().map { (s: RustStringRef) -> TextAnnotation in let d = s.as_str().toString().data(using: .utf8) ?? Data(); return try JSONDecoder().decode(TextAnnotation.self, from: d) }
        self.attributes = try JSONDecoder().decode([String: String]?.self, from: ((rb.attributes().toString()).data(using: .utf8) ?? Data("null".utf8)))
    }

    func intoRust() throws -> RustBridge.DocumentNode {
        let data = try JSONEncoder().encode(self)
        let json = String(data: data, encoding: .utf8) ?? "{}"
        return try alefBridgedCall { try RustBridge.documentNodeFromJson(json) }
    }
}

