/// A single tracked change embedded in a document.
///
/// Populated by per-format extractors that understand change-tracking metadata
/// (DOCX `w:ins`/`w:del`/`w:rPrChange`, ODT `text:change-*`, …). Every
/// extractor defaults to `ExtractedDocument.revisions = None` until a
/// format-specific implementation is added.
public struct DocumentRevision: Codable, Sendable, Hashable {
    /// Format-specific revision identifier.
    ///
    /// For DOCX this is the `w:id` attribute value on the change element
    /// (e.g. `"42"`). When the attribute is absent a synthetic fallback is
    /// generated (`"docx-ins-0"`, `"docx-del-3"`, …).
    public let revisionId: String
    /// Display name of the author who made this change, when available.
    public let author: String?
    /// ISO-8601 timestamp of the change, when available.
    ///
    /// Stored as a plain string so this type remains FFI-friendly and
    /// unconditionally available without the `chrono` optional dep.
    /// DOCX populates this from the `w:date` attribute (e.g.
    /// `"2024-03-15T10:30:00Z"`).
    public let timestamp: String?
    /// Semantic kind of this revision.
    public let kind: RevisionKind
    /// Best-effort document location for this revision.
    ///
    /// Resolution is format-dependent and may be `None` when the location
    /// cannot be determined (e.g. changes inside table cells before
    /// table-cell anchor support is added).
    public let anchor: RevisionAnchor?
    /// The content changes that make up this revision.
    public let delta: RevisionDelta
    public init(revisionId: String, author: String? = nil, timestamp: String? = nil, kind: RevisionKind, anchor: RevisionAnchor? = nil, delta: RevisionDelta) {
        self.revisionId = revisionId
        self.author = author
        self.timestamp = timestamp
        self.kind = kind
        self.anchor = anchor
        self.delta = delta
    }
    private enum CodingKeys: String, CodingKey {
        case revisionId = "revision_id"
        case author = "author"
        case timestamp = "timestamp"
        case kind = "kind"
        case anchor = "anchor"
        case delta = "delta"
    }
}

// MARK: - Internal FFI conversions for DocumentRevision
internal extension DocumentRevision {
    init(_ rb: RustBridge.DocumentRevisionRef) throws {
        self.revisionId = rb.revisionId().toString()
        self.author = rb.author()?.toString()
        self.timestamp = rb.timestamp()?.toString()
        self.kind = try { let rawValue = rb.kind().toString(); guard let value = RevisionKind(rawValue: rawValue) else { throw JobError.validation(message: "Unknown RevisionKind variant", source: rawValue) }; return value }()
        self.anchor = try JSONDecoder().decode(RevisionAnchor?.self, from: ((rb.anchor()?.toString() ?? "null").data(using: .utf8) ?? Data("null".utf8)))
        self.delta = try RevisionDelta(rb.delta())
    }

    func intoRust() throws -> RustBridge.DocumentRevision {
        let data = try JSONEncoder().encode(self)
        let json = String(data: data, encoding: .utf8) ?? "{}"
        return try alefBridgedCall { try RustBridge.documentRevisionFromJson(json) }
    }
}

/// Top-level structured document representation.
///
/// A flat array of nodes with index-based parent/child references forming a tree.
/// Root-level nodes have `parent: None`. Use `body_roots()` and `furniture_roots()`
/// to iterate over top-level content by layer.
///
/// # Validation
///
/// Call `validate()` after construction to verify all node indices are in bounds
/// and parent-child relationships are bidirectionally consistent.
public struct DocumentStructure: Codable, Sendable, Hashable {
    /// All nodes in document/reading order.
    public let nodes: [DocumentNode]
    /// Origin format identifier (e.g. "docx", "pptx", "html", "pdf").
    ///
    /// Allows renderers to apply format-aware heuristics when converting
    /// the document tree to output formats.
    public let sourceFormat: String?
    /// Resolved relationships between nodes (footnote refs, citations, anchor links, etc.).
    ///
    /// Populated during derivation from the internal document representation.
    /// Empty when no relationships are detected.
    public let relationships: [DocumentRelationship]
    /// Sorted, deduplicated list of node type names present in this document.
    ///
    /// Each value is the snake_case `node_type` tag of the corresponding
    /// [`NodeContent`] variant (e.g. `"paragraph"`, `"heading"`, `"table"`, …).
    ///
    /// Computed from `nodes` via [`DocumentStructure::finalize_node_types`].
    /// Empty until that method is called (internal construction paths call it
    /// at the end of derivation).
    public let nodeTypes: [String]
    public init(nodes: [DocumentNode] = [], sourceFormat: String? = nil, relationships: [DocumentRelationship] = [], nodeTypes: [String] = []) {
        self.nodes = nodes
        self.sourceFormat = sourceFormat
        self.relationships = relationships
        self.nodeTypes = nodeTypes
    }
    private enum CodingKeys: String, CodingKey {
        case nodes = "nodes"
        case sourceFormat = "source_format"
        case relationships = "relationships"
        case nodeTypes = "node_types"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if container.contains(.nodes) {
            self.nodes = try container.decode([DocumentNode].self, forKey: .nodes)
        } else {
            self.nodes = []
        }
        self.sourceFormat = try container.decodeIfPresent(String.self, forKey: .sourceFormat) ?? nil
        if container.contains(.relationships) {
            self.relationships = try container.decode([DocumentRelationship].self, forKey: .relationships)
        } else {
            self.relationships = []
        }
        if container.contains(.nodeTypes) {
            self.nodeTypes = try container.decode([String].self, forKey: .nodeTypes)
        } else {
            self.nodeTypes = []
        }
    }
}

// MARK: - Internal FFI conversions for DocumentStructure
internal extension DocumentStructure {
    init(_ rb: RustBridge.DocumentStructureRef) throws {
        self.nodes = try rb.nodes().map { (s: RustStringRef) -> DocumentNode in let d = s.as_str().toString().data(using: .utf8) ?? Data(); return try JSONDecoder().decode(DocumentNode.self, from: d) }
        self.sourceFormat = rb.sourceFormat()?.toString()
        self.relationships = try rb.relationships().map { (s: RustStringRef) -> DocumentRelationship in let d = s.as_str().toString().data(using: .utf8) ?? Data(); return try JSONDecoder().decode(DocumentRelationship.self, from: d) }
        self.nodeTypes = rb.nodeTypes().map { $0.as_str().toString() }
    }

    func intoRust() throws -> RustBridge.DocumentStructure {
        let __nodes = RustVec<RustBridge.DocumentNode>()
        for __elem in self.nodes { __nodes.push(value: try __elem.intoRust()) }
        let __relationships = RustVec<RustBridge.DocumentRelationship>()
        for __elem in self.relationships { __relationships.push(value: try __elem.intoRust()) }
        let __nodeTypes = RustVec<RustString>()
        for __elem in self.nodeTypes { __nodeTypes.push(value: RustString(__elem)) }
        return RustBridge.DocumentStructure(__nodes, self.sourceFormat.map(RustString.init), __relationships, __nodeTypes)
    }
}

