/// One finding reported by an external content-inspection engine.
///
/// Unknown fields are ignored, so an engine's raw output can be passed as is.
/// Presidio, AWS Comprehend, Azure Language, and GCP DLP payload fields are
/// accepted as aliases. GCP's ordered likelihood buckets are normalized to
/// evenly spaced scores from `0.0` through `1.0`; `LIKELIHOOD_UNSPECIFIED`
/// maps to `0.5`, matching GCP's documented `POSSIBLE` default.
public struct ExternalRedactionFinding: Codable, Sendable, Hashable {
    /// Engine category, surfaced as `PiiCategory::Custom(label)`.
    public let label: String
    /// Literal value to redact. When absent, it is read from `content` at
    /// `start..end` under the requested [`RedactionOffsetEncoding`].
    public let text: String?
    /// Start offset (inclusive) into `content`.
    public let start: UInt32?
    /// End offset (exclusive) into `content`.
    public let end: UInt32?
    /// Engine confidence in `[0.0, 1.0]`; filtered by [`RedactionConfig::min_score`] when set.
    public let score: Float?
    public init(label: String, text: String? = nil, start: UInt32? = nil, end: UInt32? = nil, score: Float? = nil) {
        self.label = label
        self.text = text
        self.start = start
        self.end = end
        self.score = score
    }
    private enum CodingKeys: String, CodingKey {
        case label = "label"
        case text = "text"
        case start = "start"
        case end = "end"
        case score = "score"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if container.contains(.label) {
            self.label = try container.decode(String.self, forKey: .label)
        } else {
            self.label = ""
        }
        self.text = try container.decodeIfPresent(String.self, forKey: .text) ?? nil
        self.start = try container.decodeIfPresent(UInt32.self, forKey: .start) ?? nil
        self.end = try container.decodeIfPresent(UInt32.self, forKey: .end) ?? nil
        self.score = try container.decodeIfPresent(Float.self, forKey: .score) ?? nil
    }
}

// MARK: - Internal FFI conversions for ExternalRedactionFinding
internal extension ExternalRedactionFinding {
    init(_ rb: RustBridge.ExternalRedactionFindingRef) throws {
        self.label = rb.label().toString()
        self.text = rb.text()?.toString()
        self.start = rb.start()
        self.end = rb.end()
        self.score = rb.score()
    }

    func intoRust() throws -> RustBridge.ExternalRedactionFinding {
        return RustBridge.ExternalRedactionFinding(RustString(self.label), self.text.map(RustString.init), self.start, self.end, self.score)
    }
