            self.results = 0
        }
        if container.contains(.errors) {
            self.errors = try container.decode(UInt.self, forKey: .errors)
        } else {
            self.errors = 0
        }
        if container.contains(.remoteUrls) {
            self.remoteUrls = try container.decode(UInt.self, forKey: .remoteUrls)
