/// Individual grid cell with position and span metadata.
public struct GridCell: Codable, Sendable, Hashable {
    /// Cell text content.
    public let content: String
    /// Zero-indexed row position.
    public let row: UInt32
    /// Zero-indexed column position.
    public let col: UInt32
    /// Number of rows this cell spans.
    public let rowSpan: UInt32
    /// Number of columns this cell spans.
    public let colSpan: UInt32
    /// Whether this is a header cell.
    public let isHeader: Bool
    /// Bounding box for this cell (if available).
    public let bbox: BoundingBox?
    /// Outline level (1-6) of the heading style this cell's text carries, when it has one.
    ///
    /// A DOCX banner row -- row 0, one cell spanning the grid, styled `Heading1`..`Heading6` --
    /// is what Word's navigation pane and a `TOC` field treat as the document's outline, but as
    /// a table cell it reached consumers as anonymous text (GH#1587). `content` is deliberately
    /// left as the bare cell text: prefixing it with `#` would put a markdown heading inside a
    /// table cell, which is invalid where it lands and changes text every existing consumer
    /// already reads. This field is the signal instead, so a caller can decide for itself
    /// whether a `heading 2` in a banner row is a section title or a column label.
    public let headingLevel: UInt8?
    /// Human-readable name of the paragraph style applied to this cell's text (`heading 2`).
    ///
    /// Carries the style even when it resolves to no outline level, so a caller can key on a
    /// named style this crate does not map to a heading. See [`GridCell::heading_level`].
    public let styleName: String?
    public init(content: String, row: UInt32, col: UInt32, rowSpan: UInt32 = 1, colSpan: UInt32 = 1, isHeader: Bool, bbox: BoundingBox? = nil, headingLevel: UInt8? = nil, styleName: String? = nil) {
        self.content = content
        self.row = row
        self.col = col
        self.rowSpan = rowSpan
        self.colSpan = colSpan
        self.isHeader = isHeader
        self.bbox = bbox
        self.headingLevel = headingLevel
        self.styleName = styleName
    }
    private enum CodingKeys: String, CodingKey {
        case content = "content"
        case row = "row"
        case col = "col"
        case rowSpan = "row_span"
        case colSpan = "col_span"
        case isHeader = "is_header"
        case bbox = "bbox"
        case headingLevel = "heading_level"
        case styleName = "style_name"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.content = try container.decode(String.self, forKey: .content)
        self.row = try container.decode(UInt32.self, forKey: .row)
        self.col = try container.decode(UInt32.self, forKey: .col)
        if container.contains(.rowSpan) {
            self.rowSpan = try container.decode(UInt32.self, forKey: .rowSpan)
        } else {
            self.rowSpan = 1
        }
        if container.contains(.colSpan) {
            self.colSpan = try container.decode(UInt32.self, forKey: .colSpan)
        } else {
            self.colSpan = 1
        }
        if container.contains(.isHeader) {
            self.isHeader = try container.decode(Bool.self, forKey: .isHeader)
        } else {
            self.isHeader = false
        }
        self.bbox = try container.decodeIfPresent(BoundingBox.self, forKey: .bbox) ?? nil
        self.headingLevel = try container.decodeIfPresent(UInt8.self, forKey: .headingLevel) ?? nil
        self.styleName = try container.decodeIfPresent(String.self, forKey: .styleName) ?? nil
    }
}

// MARK: - Internal FFI conversions for GridCell
internal extension GridCell {
    init(_ rb: RustBridge.GridCellRef) throws {
        self.content = rb.content().toString()
        self.row = rb.row()
        self.col = rb.col()
        self.rowSpan = rb.rowSpan()
        self.colSpan = rb.colSpan()
        self.isHeader = rb.isHeader()
        self.bbox = try rb.bbox().map { try BoundingBox($0) }
        self.headingLevel = rb.headingLevel()
