/// A unified OCR element representing detected text with full metadata.
///
/// This is the primary type for structured OCR output, preserving all information
/// from both Tesseract and PaddleOCR backends.
public struct OcrElement: Codable, Sendable, Hashable {
    /// The recognized text content.
    public let text: String
    /// Bounding geometry (rectangle or quadrilateral).
    public let geometry: OcrBoundingGeometry
    /// Confidence scores for detection and recognition.
    public let confidence: OcrConfidence
    /// Hierarchical level (word, line, block, page).
    public let level: OcrElementLevel
    /// Rotation information (if detected).
    public let rotation: OcrRotation?
    /// Page number (1-indexed).
    public let pageNumber: UInt32
    /// Parent element ID for hierarchical relationships.
    ///
    /// When hierarchy output is enabled, this resolves to another emitted element's
    /// `backend_metadata["element_id"]` value.
    public let parentId: String?
    /// Backend-specific metadata that doesn't fit the unified schema.
    public let backendMetadata: [String: JSONValue]
    public init(text: String, geometry: OcrBoundingGeometry, confidence: OcrConfidence, level: OcrElementLevel, rotation: OcrRotation? = nil, pageNumber: UInt32 = 1, parentId: String? = nil, backendMetadata: [String: JSONValue] = [:]) {
        self.text = text
        self.geometry = geometry
        self.confidence = confidence
        self.level = level
        self.rotation = rotation
        self.pageNumber = pageNumber
        self.parentId = parentId
        self.backendMetadata = backendMetadata
    }
    private enum CodingKeys: String, CodingKey {
        case text = "text"
        case geometry = "geometry"
        case confidence = "confidence"
        case level = "level"
        case rotation = "rotation"
        case pageNumber = "page_number"
        case parentId = "parent_id"
        case backendMetadata = "backend_metadata"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if container.contains(.text) {
            self.text = try container.decode(String.self, forKey: .text)
        } else {
            self.text = ""
        }
        self.geometry = try container.decode(OcrBoundingGeometry.self, forKey: .geometry)
        self.confidence = try container.decode(OcrConfidence.self, forKey: .confidence)
        self.level = try container.decode(OcrElementLevel.self, forKey: .level)
        self.rotation = try container.decodeIfPresent(OcrRotation.self, forKey: .rotation) ?? nil
        if container.contains(.pageNumber) {
            self.pageNumber = try container.decode(UInt32.self, forKey: .pageNumber)
        } else {
            self.pageNumber = 1
        }
        self.parentId = try container.decodeIfPresent(String.self, forKey: .parentId) ?? nil
        if container.contains(.backendMetadata) {
            self.backendMetadata = try container.decode([String: JSONValue].self, forKey: .backendMetadata)
        } else {
            self.backendMetadata = [:]
        }
    }
}

