/// Configuration for OCR element extraction.
///
/// Controls how OCR elements are extracted and filtered.
public struct OcrElementConfig: Codable, Sendable, Hashable {
    /// Whether to include OCR elements in the extraction result.
    ///
    /// When true, the `ocr_elements` field in `ExtractedDocument` will be populated.
    public let includeElements: Bool
    /// Minimum hierarchical level to include.
    ///
    /// Elements below this level (e.g., words when min_level is Line) will be excluded.
    public let minLevel: OcrElementLevel
    /// Minimum recognition confidence threshold (0.0-1.0).
    ///
    /// Elements with confidence below this threshold will be filtered out.
    public let minConfidence: Double
    /// Whether to build hierarchical relationships between elements.
    ///
    /// When true, emitted elements receive an `element_id` metadata value and `parent_id`
    /// references are populated only when a spatially containing parent is also emitted.
    public let buildHierarchy: Bool
    public init(includeElements: Bool, minLevel: OcrElementLevel, minConfidence: Double, buildHierarchy: Bool) {
        self.includeElements = includeElements
        self.minLevel = minLevel
        self.minConfidence = minConfidence
        self.buildHierarchy = buildHierarchy
    }
    private enum CodingKeys: String, CodingKey {
        case includeElements = "include_elements"
        case minLevel = "min_level"
        case minConfidence = "min_confidence"
        case buildHierarchy = "build_hierarchy"
    }
    private struct AlefWireKey: CodingKey {
        let stringValue: String
        var intValue: Int? { nil }
        init?(stringValue: String) { self.stringValue = stringValue }
        init?(intValue: Int) { return nil }
    }
    public init(from decoder: any Decoder) throws {
        let allFields = try decoder.container(keyedBy: AlefWireKey.self)
        if let key = allFields.allKeys.first(where: { CodingKeys(rawValue: $0.stringValue) == nil }) {
            throw DecodingError.dataCorruptedError(forKey: key, in: allFields, debugDescription: "Unknown field")
        }
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if container.contains(.includeElements) {
            self.includeElements = try container.decode(Bool.self, forKey: .includeElements)
        } else {
            self.includeElements = false
        }
        self.minLevel = try container.decode(OcrElementLevel.self, forKey: .minLevel)
        if container.contains(.minConfidence) {
            self.minConfidence = try container.decode(Double.self, forKey: .minConfidence)
        } else {
            self.minConfidence = 0
        }
        if container.contains(.buildHierarchy) {
            self.buildHierarchy = try container.decode(Bool.self, forKey: .buildHierarchy)
        } else {
            self.buildHierarchy = false
        }
    }
}

// MARK: - Internal FFI conversions for OcrElementConfig
internal extension OcrElementConfig {
    init(_ rb: RustBridge.OcrElementConfigRef) throws {
        self.includeElements = rb.includeElements()
        self.minLevel = try { let rawValue = rb.minLevel().toString(); guard let value = OcrElementLevel(rawValue: rawValue) else { throw JobError.validation(message: "Unknown OcrElementLevel variant", source: rawValue) }; return value }()
