/// Page extraction and tracking configuration.
///
/// Controls how pages are extracted, tracked, and represented in the extraction results.
/// When `None`, page tracking is disabled.
///
/// Page range tracking in chunk metadata (first_page/last_page) is automatically enabled
/// when page boundaries are available and chunking is configured.
public struct PageConfig: Codable, Sendable, Hashable {
    /// Extract pages as separate array (ExtractedDocument.pages)
    public let extractPages: Bool
    /// Insert page markers in main content string
    public let insertPageMarkers: Bool
    /// Page marker format (use {page_num} placeholder)
    /// Default: "\n\n<!-- PAGE {page_num} -->\n\n"
    public let markerFormat: String
    /// Keep the text layer of a PDF page whose `content` OCR output replaces, for a caller that needs the exact
    /// characters of a short born-digital page. The text layer is returned in `PageContent::native_content`.
    /// Needs `extract_pages`.
    public let keepNativeContent: Bool
    public init(extractPages: Bool = false, insertPageMarkers: Bool = false, markerFormat: String = "\n\n<!-- PAGE {page_num} -->\n\n", keepNativeContent: Bool = false) {
        self.extractPages = extractPages
        self.insertPageMarkers = insertPageMarkers
        self.markerFormat = markerFormat
        self.keepNativeContent = keepNativeContent
    }
    private enum CodingKeys: String, CodingKey {
        case extractPages = "extract_pages"
        case insertPageMarkers = "insert_page_markers"
        case markerFormat = "marker_format"
        case keepNativeContent = "keep_native_content"
    }
    private struct AlefWireKey: CodingKey {
        let stringValue: String
        var intValue: Int? { nil }
        init?(stringValue: String) { self.stringValue = stringValue }
        init?(intValue: Int) { return nil }
    }
    public init(from decoder: any Decoder) throws {
        let allFields = try decoder.container(keyedBy: AlefWireKey.self)
        if let key = allFields.allKeys.first(where: { CodingKeys(rawValue: $0.stringValue) == nil }) {
            throw DecodingError.dataCorruptedError(forKey: key, in: allFields, debugDescription: "Unknown field")
        }
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if container.contains(.extractPages) {
            self.extractPages = try container.decode(Bool.self, forKey: .extractPages)
        } else {
            self.extractPages = false
        }
        if container.contains(.insertPageMarkers) {
            self.insertPageMarkers = try container.decode(Bool.self, forKey: .insertPageMarkers)
        } else {
            self.insertPageMarkers = false
        }
        if container.contains(.markerFormat) {
            self.markerFormat = try container.decode(String.self, forKey: .markerFormat)
        } else {
            self.markerFormat = "\n\n<!-- PAGE {page_num} -->\n\n"
        }
        if container.contains(.keepNativeContent) {
            self.keepNativeContent = try container.decode(Bool.self, forKey: .keepNativeContent)
        } else {
            self.keepNativeContent = false
        }
    }
}

