/// Content for a single page/slide.
///
/// When page extraction is enabled, documents are split into per-page content
/// with associated tables and images mapped to each page.
///
/// # Performance
///
/// Uses Arc-wrapped tables and images for memory efficiency:
/// - `Vec<Arc<Table>>` enables zero-copy sharing of table data
/// - `Vec<Arc<ExtractedImage>>` enables zero-copy sharing of image data
/// - Maintains exact JSON compatibility via custom Serialize/Deserialize
///
/// This reduces memory overhead for documents with shared tables/images
/// by avoiding redundant copies during serialization.
public struct PageContent: Codable, Sendable, Hashable {
    /// Page number (1-indexed)
    public let pageNumber: UInt32
    /// Text content for this page
    public let content: String
    /// Tables found on this page (uses Arc for memory efficiency)
    ///
    /// Serializes as `Vec<Table>` for JSON compatibility while maintaining
    /// Arc semantics in-memory for zero-copy sharing.
    public let tables: [Table]
    /// Indices into `ExtractedDocument.images` for images found on this page.
    ///
    /// Each value is a zero-based index into the top-level `images` collection.
    /// Only populated when `extract_images = true` in the extraction config.
    public let imageIndices: [UInt32]
    /// OCR image preprocessing applied to this page's raster.
    public let imagePreprocessing: ImagePreprocessingMetadata?
    /// Hierarchy information for the page (when hierarchy extraction is enabled)
    ///
    /// Contains text hierarchy levels (H1-H6) extracted from the page content.
    public let hierarchy: PageHierarchy?
    /// Whether this page is blank (no meaningful text content)
    ///
    /// Determined during extraction based on text content analysis.
    /// A page is blank if it has fewer than 3 non-whitespace characters
    /// and contains no tables or images.
    public let isBlank: Bool?
    /// Layout detection regions for this page (when layout detection is enabled).
    ///
    /// Contains detected layout regions with class, confidence, bounding box,
    /// and area fraction. Only populated when layout detection is configured.
    public let layoutRegions: [LayoutRegion]?
    /// Speaker notes for this slide (PPTX only).
    ///
    /// Contains the text from the slide's notes pane (`ppt/notesSlides/notesSlide{N}.xml`).
    /// Only populated when the source is a PPTX file and notes are present.
    public let speakerNotes: String?
    /// Section name this slide belongs to (PPTX only).
    ///
    /// PowerPoint sections group slides into logical chapters (`<p:sectionLst>` in
    /// `ppt/presentation.xml`). Only populated when the source is a PPTX file and
    /// the slide belongs to a named section.
    public let sectionName: String?
    /// Sheet name for this page (XLSX/ODS only).
    ///
    /// Each spreadsheet sheet maps to one `PageContent` entry. This field carries the
    /// sheet's display name as it appears in the workbook. `None` for all non-spreadsheet
    /// formats and for sheets with an empty name.
    public let sheetName: String?
    /// Aggregate OCR confidence for this page. `None` when the page was not OCR'd.
    public let ocrConfidence: PageOcrConfidence?
    /// Text layer of this page, kept when OCR output replaced it in `content`.
    ///
    /// Set only when `PageConfig::keep_native_content` is on, an OCR route replaced this page's `content`, and the
    /// text layer is not blank and differs from the OCR text. `None` on every other page. PDF only.
    public let nativeContent: String?
    public init(pageNumber: UInt32, content: String, tables: [Table] = [], imageIndices: [UInt32] = [], imagePreprocessing: ImagePreprocessingMetadata? = nil, hierarchy: PageHierarchy? = nil, isBlank: Bool? = nil, layoutRegions: [LayoutRegion]? = nil, speakerNotes: String? = nil, sectionName: String? = nil, sheetName: String? = nil, ocrConfidence: PageOcrConfidence? = nil, nativeContent: String? = nil) {
        self.pageNumber = pageNumber
        self.content = content
        self.tables = tables
        self.imageIndices = imageIndices
        self.imagePreprocessing = imagePreprocessing
        self.hierarchy = hierarchy
        self.isBlank = isBlank
        self.layoutRegions = layoutRegions
        self.speakerNotes = speakerNotes
        self.sectionName = sectionName
        self.sheetName = sheetName
        self.ocrConfidence = ocrConfidence
        self.nativeContent = nativeContent
    }
    private enum CodingKeys: String, CodingKey {
        case pageNumber = "page_number"
        case content = "content"
        case tables = "tables"
        case imageIndices = "image_indices"
        case imagePreprocessing = "image_preprocessing"
        case hierarchy = "hierarchy"
        case isBlank = "is_blank"
        case layoutRegions = "layout_regions"
        case speakerNotes = "speaker_notes"
        case sectionName = "section_name"
        case sheetName = "sheet_name"
        case ocrConfidence = "ocr_confidence"
        case nativeContent = "native_content"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.pageNumber = try container.decode(UInt32.self, forKey: .pageNumber)
        self.content = try container.decode(String.self, forKey: .content)
        if container.contains(.tables) {
            self.tables = try container.decode([Table].self, forKey: .tables)
        } else {
            self.tables = []
        }
        if container.contains(.imageIndices) {
            self.imageIndices = try container.decode([UInt32].self, forKey: .imageIndices)
        } else {
            self.imageIndices = []
        }
        self.imagePreprocessing = try container.decodeIfPresent(ImagePreprocessingMetadata.self, forKey: .imagePreprocessing) ?? nil
        self.hierarchy = try container.decodeIfPresent(PageHierarchy.self, forKey: .hierarchy) ?? nil
        self.isBlank = try container.decodeIfPresent(Bool.self, forKey: .isBlank) ?? nil
        self.layoutRegions = try container.decodeIfPresent([LayoutRegion].self, forKey: .layoutRegions) ?? nil
        self.speakerNotes = try container.decodeIfPresent(String.self, forKey: .speakerNotes) ?? nil
        self.sectionName = try container.decodeIfPresent(String.self, forKey: .sectionName) ?? nil
        self.sheetName = try container.decodeIfPresent(String.self, forKey: .sheetName) ?? nil
        self.ocrConfidence = try container.decodeIfPresent(PageOcrConfidence.self, forKey: .ocrConfidence) ?? nil
        self.nativeContent = try container.decodeIfPresent(String.self, forKey: .nativeContent) ?? nil
    }
}

