        case wordCount = "word_count"
        case backend = "backend"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.score = try container.decodeIfPresent(Double.self, forKey: .score) ?? nil
        if container.contains(.wordCount) {
            self.wordCount = try container.decode(UInt32.self, forKey: .wordCount)
        } else {
            self.wordCount = 0
        }
        if container.contains(.backend) {
            self.backend = try container.decode(String.self, forKey: .backend)
        } else {
            self.backend = ""
        }
    }
}

