    /// Words that, found near a match, boost its confidence toward `1.0`
    /// (`context`). Empty for patterns with no calibrated context word list.
    public let contextWords: [String]
    public init(category: PiiCategory, pattern: String, formatPreserving: Bool, redactTemplate: String, baseConfidence: Float = 1.0, contextWords: [String]) {
        self.category = category
        self.pattern = pattern
        self.formatPreserving = formatPreserving
        self.redactTemplate = redactTemplate
        self.baseConfidence = baseConfidence
        self.contextWords = contextWords
    }
    private enum CodingKeys: String, CodingKey {
        case category = "category"
        case pattern = "pattern"
        case formatPreserving = "format_preserving"
        case redactTemplate = "redact_template"
        case baseConfidence = "base_confidence"
    }
    public init(from decoder: any Decoder) throws {
        self.contextWords = []
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.category = try container.decode(PiiCategory.self, forKey: .category)
        self.pattern = try container.decode(String.self, forKey: .pattern)
        self.formatPreserving = try container.decode(Bool.self, forKey: .formatPreserving)
        self.redactTemplate = try container.decode(String.self, forKey: .redactTemplate)
        if container.contains(.baseConfidence) {
            self.baseConfidence = try container.decode(Float.self, forKey: .baseConfidence)
        } else {
            self.baseConfidence = 1.0
        }
    }
    // MARK: - Instance Methods
    public func withBaseConfidence(baseConfidence: Float) throws  -> PatternMeta {
        let jsonSelf = try JSONEncoder().encode(self)
        let selfString = String(data: jsonSelf, encoding: .utf8) ?? "{}"
        let resultJson = try alefBridgedCall { try RustBridge.patternMetaWithBaseConfidenceFromJson(selfString, baseConfidence) }.toString()
        let data = resultJson.data(using: .utf8) ?? Data()
        return try JSONDecoder().decode(PatternMeta.self, from: data)
    }

    public func withContext(contextWords: [String]) throws  -> PatternMeta {
        let jsonSelf = try JSONEncoder().encode(self)
        let selfString = String(data: jsonSelf, encoding: .utf8) ?? "{}"
        let resultJson = try alefBridgedCall { try RustBridge.patternMetaWithContextFromJson(selfString, contextWords) }.toString()
        let data = resultJson.data(using: .utf8) ?? Data()
        return try JSONDecoder().decode(PatternMeta.self, from: data)
    }

}

