        self.metrics = try PipelineMetrics(rb.metrics())
    }

    func intoRust() throws -> RustBridge.PipelineResult {
        let __entities = RustVec<RustBridge.MergedEntity>()
        for __elem in self.entities { __entities.push(value: try __elem.intoRust()) }
