public struct RedactionConfig: Codable, Sendable, Hashable {
    public let mode: RedactionMode
    /// Template used when `mode` is [`RedactionMode::Custom`].
    ///
    /// `{{ENTITY}}` expands to the category name and `{{TEXT}}` to the original span.
    public let customTemplate: String?
    /// Keep the shape of the original span (length, separators) where the mode allows it.
    public let preserveFormat: Bool
    /// Which pseudonymisation key new tokens are minted under, when `mode` is
    /// [`RedactionMode::Pseudonymize`]. `None` means "whichever key the resolver reports
    /// as active".
    ///
    /// This is an *identifier*, never key material. The struct is serialised and printed
    /// by `config show`; putting a secret in it would put that secret in every dumped
    /// config, log line, and support bundle. Key material reaches the engine only through
    /// a [`KeyResolver`](crate::redaction::KeyResolver).
    public let keyId: String?
    public init(mode: RedactionMode, customTemplate: String? = nil, preserveFormat: Bool = true, keyId: String? = nil) {
        self.mode = mode
        self.customTemplate = customTemplate
        self.preserveFormat = preserveFormat
        self.keyId = keyId
    }
    private enum CodingKeys: String, CodingKey {
        case mode = "mode"
        case customTemplate = "custom_template"
        case preserveFormat = "preserve_format"
        case keyId = "key_id"
    }
    private struct AlefWireKey: CodingKey {
        let stringValue: String
        var intValue: Int? { nil }
        init?(stringValue: String) { self.stringValue = stringValue }
        init?(intValue: Int) { return nil }
    }
    public init(from decoder: any Decoder) throws {
        let allFields = try decoder.container(keyedBy: AlefWireKey.self)
        if let key = allFields.allKeys.first(where: { CodingKeys(rawValue: $0.stringValue) == nil }) {
            throw DecodingError.dataCorruptedError(forKey: key, in: allFields, debugDescription: "Unknown field")
        }
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.mode = try container.decode(RedactionMode.self, forKey: .mode)
        self.customTemplate = try container.decodeIfPresent(String.self, forKey: .customTemplate) ?? nil
        if container.contains(.preserveFormat) {
            self.preserveFormat = try container.decode(Bool.self, forKey: .preserveFormat)
        } else {
            self.preserveFormat = true
        }
        self.keyId = try container.decodeIfPresent(String.self, forKey: .keyId) ?? nil
    }
}

// MARK: - Internal FFI conversions for RedactionConfig
internal extension RedactionConfig {
    init(_ rb: RustBridge.RedactionConfigRef) throws {
        self.mode = try { let rawValue = rb.mode().toString(); guard let value = RedactionMode(rawValue: rawValue) else { throw JobError.validation(message: "Unknown RedactionMode variant", source: rawValue) }; return value }()
        self.customTemplate = rb.customTemplate()?.toString()
        self.preserveFormat = rb.preserveFormat()
        self.keyId = rb.keyId()?.toString()
    }

    func intoRust() throws -> RustBridge.RedactionConfig {
        return RustBridge.RedactionConfig(try self.mode.intoRust(), self.customTemplate.map(RustString.init), self.preserveFormat, self.keyId.map(RustString.init))
    }
}

