/// One user-supplied literal term to redact.
///
/// Matched as a regex-escaped substring (so callers do not need to escape
/// metacharacters themselves). Case-insensitive by default — set
/// [`Self::case_sensitive`] to `true` for exact byte-match semantics.
public struct RedactionTerm: Codable, Sendable, Hashable {
    /// Custom category label surfaced in [`RedactionFinding::category`](crate::types::redaction::RedactionFinding::category).
    public let label: String
    /// Literal value to match. Regex metacharacters are escaped automatically.
    public let value: String
    /// When `true`, match the value as-is; otherwise match ASCII-case-insensitively.
    public let caseSensitive: Bool
    public init(label: String, value: String, caseSensitive: Bool = false) {
        self.label = label
        self.value = value
        self.caseSensitive = caseSensitive
    }
    private enum CodingKeys: String, CodingKey {
        case label = "label"
        case value = "value"
        case caseSensitive = "case_sensitive"
    }
    private struct AlefWireKey: CodingKey {
        let stringValue: String
        var intValue: Int? { nil }
        init?(stringValue: String) { self.stringValue = stringValue }
        init?(intValue: Int) { return nil }
    }
    public init(from decoder: any Decoder) throws {
        let allFields = try decoder.container(keyedBy: AlefWireKey.self)
        if let key = allFields.allKeys.first(where: { CodingKeys(rawValue: $0.stringValue) == nil }) {
            throw DecodingError.dataCorruptedError(forKey: key, in: allFields, debugDescription: "Unknown field")
        }
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.label = try container.decode(String.self, forKey: .label)
        self.value = try container.decode(String.self, forKey: .value)
        if container.contains(.caseSensitive) {
            self.caseSensitive = try container.decode(Bool.self, forKey: .caseSensitive)
        } else {
            self.caseSensitive = false
        }
    }
}

// MARK: - Internal FFI conversions for RedactionTerm
internal extension RedactionTerm {
    init(_ rb: RustBridge.RedactionTermRef) throws {
        self.label = rb.label().toString()
        self.value = rb.value().toString()
        self.caseSensitive = rb.caseSensitive()
    }

    func intoRust() throws -> RustBridge.RedactionTerm {
        let data = try JSONEncoder().encode(self)
        let json = String(data: data, encoding: .utf8) ?? "{}"
        return try alefBridgedCall { try RustBridge.redactionTermFromJson(json) }
    }
}

/// A span matched by the deterministic regex engine.
public struct RegexEntity: Codable, Sendable, Hashable {
    public let category: PiiCategory
    /// Byte offset of the first byte of the span.
    public let start: UInt32
    /// Byte offset one past the last byte of the span.
    public let end: UInt32
    public let confidence: Float
    public let formatPreserving: Bool
    public let redactTemplate: String
    /// Copied from the originating [`PatternMeta::context_words`] at match time, so
    /// `enhance` can look up this span's context words without
    /// needing the pattern set that produced it back in scope. `#[serde(skip)]`: a
    /// `&'static` slice cannot round-trip through serde, and (as with
    /// [`PatternMeta::validator`]) nothing actually (de)serializes `RegexEntity` today.
    public let contextWords: [String]
    public init(category: PiiCategory, start: UInt32, end: UInt32, confidence: Float, formatPreserving: Bool, redactTemplate: String, contextWords: [String]) {
        self.category = category
        self.start = start
        self.end = end
        self.confidence = confidence
        self.formatPreserving = formatPreserving
        self.redactTemplate = redactTemplate
        self.contextWords = contextWords
    }
    private enum CodingKeys: String, CodingKey {
        case category = "category"
        case start = "start"
        case end = "end"
        case confidence = "confidence"
        case formatPreserving = "format_preserving"
        case redactTemplate = "redact_template"
    }
    public init(from decoder: any Decoder) throws {
        self.contextWords = []
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.category = try container.decode(PiiCategory.self, forKey: .category)
        self.start = try container.decode(UInt32.self, forKey: .start)
        self.end = try container.decode(UInt32.self, forKey: .end)
        self.confidence = try container.decode(Float.self, forKey: .confidence)
        self.formatPreserving = try container.decode(Bool.self, forKey: .formatPreserving)
        self.redactTemplate = try container.decode(String.self, forKey: .redactTemplate)
    }
}

// MARK: - Internal FFI conversions for RegexEntity
internal extension RegexEntity {
