/// A request to mint a [`RevealTicket`]. This is what contract B's `RehydrationRequest`
/// becomes at the authorization boundary: the *demand*, before the ticket is granted.
public struct RevealTicketRequest: Codable, Sendable, Hashable {
    /// Dossier the subject must belong to (ACL gate at mint time).
    public let dossierId: String
    /// Documents in scope — must be non-empty and contain no empty id.
    public let documentIds: [String]
    /// Explicit token ids in scope. Shape-checked at mint; unknown keys stay fail-closed
    /// (400) at resolve time, never at mint time, so minting is not a token oracle.
    public let tokenIds: [String]
    /// Category labels in scope, as an alternative to `token_ids`. At least one of
    /// `token_ids` / `field_scope` must be non-empty.
    public let fieldScope: [String]
    /// Required, non-blank justification. Written verbatim to the audit entry.
    public let justification: String
    /// Approvers. High-sensitivity scopes require >= 2 distinct approvers != subject.
    public let approvers: [String]
    /// Optional TTL in seconds; clamped to `[MIN_TICKET_TTL_SECS, MAX_TICKET_TTL_SECS]`,
    /// defaulting to [`DEFAULT_TICKET_TTL_SECS`].
    public let ttlSecs: UInt64?
    public init(dossierId: String, documentIds: [String], tokenIds: [String] = [], fieldScope: [String] = [], justification: String, approvers: [String] = [], ttlSecs: UInt64? = nil) {
        self.dossierId = dossierId
        self.documentIds = documentIds
        self.tokenIds = tokenIds
        self.fieldScope = fieldScope
        self.justification = justification
        self.approvers = approvers
        self.ttlSecs = ttlSecs
    }
    private enum CodingKeys: String, CodingKey {
        case dossierId = "dossier_id"
        case documentIds = "document_ids"
        case tokenIds = "token_ids"
        case fieldScope = "field_scope"
        case justification = "justification"
        case approvers = "approvers"
        case ttlSecs = "ttl_secs"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.dossierId = try container.decode(String.self, forKey: .dossierId)
        self.documentIds = try container.decode([String].self, forKey: .documentIds)
        if container.contains(.tokenIds) {
            self.tokenIds = try container.decode([String].self, forKey: .tokenIds)
        } else {
            self.tokenIds = []
        }
        if container.contains(.fieldScope) {
            self.fieldScope = try container.decode([String].self, forKey: .fieldScope)
        } else {
            self.fieldScope = []
        }
        self.justification = try container.decode(String.self, forKey: .justification)
        if container.contains(.approvers) {
            self.approvers = try container.decode([String].self, forKey: .approvers)
        } else {
            self.approvers = []
        }
        self.ttlSecs = try container.decodeIfPresent(UInt64.self, forKey: .ttlSecs) ?? nil
    }
}

// MARK: - Internal FFI conversions for RevealTicketRequest
internal extension RevealTicketRequest {
    init(_ rb: RustBridge.RevealTicketRequestRef) throws {
        self.dossierId = rb.dossierId().toString()
        self.documentIds = rb.documentIds().map { $0.as_str().toString() }
        self.tokenIds = rb.tokenIds().map { $0.as_str().toString() }
