/// A single item awaiting (or having received) human review.
///
/// # Tenant scoping (S1b)
///
/// `tenant_id` travels with the item rather than being a repeated parameter on every
/// `ReviewStore` method — see that trait's doc and
/// `tenancy.rs`'s module doc (decision D-S1-1) for why a store method still takes
/// `&TenantId` explicitly wherever it cannot resolve the tenant from an item it already
/// has in hand (`list`/`get`/`stats`, and the pre-lookup half of `assign`/`decide`).
public struct ReviewQueueItem: Codable, Sendable, Hashable {
    public let id: String
    public let textSnippet: String
    public let category: String
    public let start: UInt32
    public let end: UInt32
    public let confidence: Float
    public let source: String
    public let status: ReviewStatus
    public let priority: Priority
    public let assignedReviewer: String?
    public let createdAt: String
    public let deadline: String?
    public let decision: ReviewDecision?
    public let decidedBy: String?
    public let decidedAt: String?
    public let comment: String?
    /// The tenant this item belongs to (S1). Set by
    /// [`ReviewQueue::submit`](crate::review::ReviewQueue::submit) — always `"default"`
    /// until a caller uses
    /// [`ReviewQueue::submit_for_tenant`](crate::review::ReviewQueue::submit_for_tenant).
    ///
    /// Defaulted on deserialize: a record written by `FileReviewStore` before S1b
    /// shipped this field has no `tenant_id` key in its JSONL line at all, and every
    /// such record was, in effect, created for the single pre-tenancy deployment this
    /// default names explicitly. Without it, `FileReviewStore::open`'s replay would
    /// fail outright on any log written before this change (`review/store_file.rs`
    /// reads exactly this struct back via `serde_json`).
    public let tenantId: String
    public init(id: String, textSnippet: String, category: String, start: UInt32, end: UInt32, confidence: Float, source: String, status: ReviewStatus, priority: Priority, assignedReviewer: String? = nil, createdAt: String, deadline: String? = nil, decision: ReviewDecision? = nil, decidedBy: String? = nil, decidedAt: String? = nil, comment: String? = nil, tenantId: String) {
        self.id = id
        self.textSnippet = textSnippet
        self.category = category
        self.start = start
        self.end = end
        self.confidence = confidence
        self.source = source
        self.status = status
        self.priority = priority
        self.assignedReviewer = assignedReviewer
        self.createdAt = createdAt
        self.deadline = deadline
        self.decision = decision
        self.decidedBy = decidedBy
        self.decidedAt = decidedAt
        self.comment = comment
        self.tenantId = tenantId
    }
    private enum CodingKeys: String, CodingKey {
        case id = "id"
        case textSnippet = "text_snippet"
        case category = "category"
        case start = "start"
        case end = "end"
        case confidence = "confidence"
        case source = "source"
        case status = "status"
        case priority = "priority"
        case assignedReviewer = "assigned_reviewer"
        case createdAt = "created_at"
        case deadline = "deadline"
        case decision = "decision"
        case decidedBy = "decided_by"
        case decidedAt = "decided_at"
        case comment = "comment"
        case tenantId = "tenant_id"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.id = try container.decode(String.self, forKey: .id)
        self.textSnippet = try container.decode(String.self, forKey: .textSnippet)
        self.category = try container.decode(String.self, forKey: .category)
        self.start = try container.decode(UInt32.self, forKey: .start)
        self.end = try container.decode(UInt32.self, forKey: .end)
        self.confidence = try container.decode(Float.self, forKey: .confidence)
        self.source = try container.decode(String.self, forKey: .source)
        self.status = try container.decode(ReviewStatus.self, forKey: .status)
        self.priority = try container.decode(Priority.self, forKey: .priority)
        self.assignedReviewer = try container.decodeIfPresent(String.self, forKey: .assignedReviewer) ?? nil
        self.createdAt = try container.decode(String.self, forKey: .createdAt)
        self.deadline = try container.decodeIfPresent(String.self, forKey: .deadline) ?? nil
        self.decision = try container.decodeIfPresent(ReviewDecision.self, forKey: .decision) ?? nil
        self.decidedBy = try container.decodeIfPresent(String.self, forKey: .decidedBy) ?? nil
        self.decidedAt = try container.decodeIfPresent(String.self, forKey: .decidedAt) ?? nil
        self.comment = try container.decodeIfPresent(String.self, forKey: .comment) ?? nil
        self.tenantId = try container.decode(String.self, forKey: .tenantId)
    }
}

