/// Configuration for security limits across extractors.
///
/// All limits are intentionally conservative to prevent DoS attacks
/// while still supporting legitimate documents.
public struct SecurityLimits: Codable, Sendable, Hashable {
    /// Maximum uncompressed size for archives (500 MB)
    public let maxArchiveSize: UInt
    /// Maximum compression ratio before flagging as potential bomb (100:1)
    public let maxCompressionRatio: UInt
    /// Maximum number of files in archive (10,000)
    public let maxFilesInArchive: UInt
    /// Maximum nesting depth for structures (1024)
    public let maxNestingDepth: UInt
    /// Maximum length of any single XML entity / attribute / token (1 MiB).
    /// This is a per-token cap, NOT a total cap — billion-laughs class
    /// attacks where a single entity expands to hundreds of MB are caught
    /// here, while normal long text content (a paragraph, a CDATA block) is
    /// caught by `max_content_size` instead.
    public let maxEntityLength: UInt
    /// Maximum string growth and decoded image allocation per operation (100 MB).
    ///
    /// Per-page passes such as layout detection charge each batch against this limit,
    /// not the whole document; only `max_pages` bounds the rasters retained across a
    /// document (GH#1721).
    public let maxContentSize: UInt
    /// Maximum iterations per operation.
    ///
    /// For external redaction findings, this may lower but cannot raise the
    /// fixed 10,000-finding ceiling.
    public let maxIterations: UInt
    /// Maximum XML depth (1024 levels)
    public let maxXmlDepth: UInt
    /// Maximum aggregate table cells per document (100,000).
    ///
    /// Raise this for trusted large tabular inputs. Higher values permit
    /// proportionally more parsing work and output allocation. A spreadsheet
    /// workbook (XLSX, XLSM, XLTM, XLAM, XLSB, XLS, XLA, ODS) over the limit is not rejected: each
    /// sheet that does not fit the remaining budget is skipped with a warning
    /// and returned empty, so a workbook whose every sheet is over the limit
    /// yields placeholder sheets only. Other table formats fail with a
    /// security error.
    public let maxTableCells: UInt
    /// Maximum number of pages (or slides, or frames) in a single document.
    /// `None` means unlimited.
    ///
    /// Checked once the count is known and before any per-page work (OCR, layout
    /// detection, rendering) starts. Byte-size limits do not bound page count: a
    /// scanned page can compress to a few kilobytes, so a document well under
    /// `max_content_size` or `max_archive_size` can still hold thousands of pages
    /// of per-page work. Defaults to `None` (unlimited) because a real ceiling
    /// here is workload-specific and a low default would silently reject
    /// legitimate large documents; callers that want a ceiling set this
    /// explicitly.
    ///
    /// Enforced for: PDF (`extractors::pdf`, page count via `xberg_native_pdf`/`lopdf`),
    /// PPTX (`extraction::pptx`, slide count from the archive's slide parts),
    /// Keynote (`extractors::iwork::keynote`, slide count from `Index/Slide-*.iwa`
    /// entry names), ODP (`extractors::odp`, `draw:page` count in `content.xml`),
    /// and multi-frame TIFF images built with the `ocr` feature
    /// (`extractors::image`, frame count via the `tiff` crate). Not enforced for
    /// any other format, including DOCX, ODT, XLSX, legacy PPT/DOC, Pages/Numbers,
    /// and TIFF images when the `ocr` feature is disabled: those formats either
    /// have no fixed "page" the crate can count without doing the expensive work
    /// itself (DOCX/ODT page count is a layout outcome, not a stored value), or
    /// have no per-page pipeline to gate at all. Setting `max_pages` on a
    /// document of an unenforced format is silently a no-op, not a guarantee.
    public let maxPages: UInt?
    public init(maxArchiveSize: UInt = 524288000, maxCompressionRatio: UInt = 100, maxFilesInArchive: UInt = 10000, maxNestingDepth: UInt = 1024, maxEntityLength: UInt = 1048576, maxContentSize: UInt = 104857600, maxIterations: UInt = 10000000, maxXmlDepth: UInt = 1024, maxTableCells: UInt = 100000, maxPages: UInt? = nil) {
        self.maxArchiveSize = maxArchiveSize
        self.maxCompressionRatio = maxCompressionRatio
        self.maxFilesInArchive = maxFilesInArchive
        self.maxNestingDepth = maxNestingDepth
        self.maxEntityLength = maxEntityLength
        self.maxContentSize = maxContentSize
        self.maxIterations = maxIterations
        self.maxXmlDepth = maxXmlDepth
        self.maxTableCells = maxTableCells
        self.maxPages = maxPages
    }
    private enum CodingKeys: String, CodingKey {
        case maxArchiveSize = "max_archive_size"
        case maxCompressionRatio = "max_compression_ratio"
        case maxFilesInArchive = "max_files_in_archive"
        case maxNestingDepth = "max_nesting_depth"
        case maxEntityLength = "max_entity_length"
        case maxContentSize = "max_content_size"
        case maxIterations = "max_iterations"
        case maxXmlDepth = "max_xml_depth"
        case maxTableCells = "max_table_cells"
        case maxPages = "max_pages"
    }
    private struct AlefWireKey: CodingKey {
        let stringValue: String
        var intValue: Int? { nil }
        init?(stringValue: String) { self.stringValue = stringValue }
        init?(intValue: Int) { return nil }
    }
    public init(from decoder: any Decoder) throws {
        let allFields = try decoder.container(keyedBy: AlefWireKey.self)
        if let key = allFields.allKeys.first(where: { CodingKeys(rawValue: $0.stringValue) == nil }) {
            throw DecodingError.dataCorruptedError(forKey: key, in: allFields, debugDescription: "Unknown field")
        }
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if container.contains(.maxArchiveSize) {
            self.maxArchiveSize = try container.decode(UInt.self, forKey: .maxArchiveSize)
        } else {
            self.maxArchiveSize = 524288000
        }
        if container.contains(.maxCompressionRatio) {
            self.maxCompressionRatio = try container.decode(UInt.self, forKey: .maxCompressionRatio)
        } else {
            self.maxCompressionRatio = 100
        }
        if container.contains(.maxFilesInArchive) {
            self.maxFilesInArchive = try container.decode(UInt.self, forKey: .maxFilesInArchive)
        } else {
            self.maxFilesInArchive = 10000
        }
        if container.contains(.maxNestingDepth) {
            self.maxNestingDepth = try container.decode(UInt.self, forKey: .maxNestingDepth)
        } else {
            self.maxNestingDepth = 1024
        }
        if container.contains(.maxEntityLength) {
            self.maxEntityLength = try container.decode(UInt.self, forKey: .maxEntityLength)
        } else {
            self.maxEntityLength = 1048576
        }
        if container.contains(.maxContentSize) {
            self.maxContentSize = try container.decode(UInt.self, forKey: .maxContentSize)
        } else {
            self.maxContentSize = 104857600
        }
        if container.contains(.maxIterations) {
            self.maxIterations = try container.decode(UInt.self, forKey: .maxIterations)
        } else {
            self.maxIterations = 10000000
        }
        if container.contains(.maxXmlDepth) {
            self.maxXmlDepth = try container.decode(UInt.self, forKey: .maxXmlDepth)
        } else {
            self.maxXmlDepth = 1024
        }
        if container.contains(.maxTableCells) {
            self.maxTableCells = try container.decode(UInt.self, forKey: .maxTableCells)
        } else {
            self.maxTableCells = 100000
        }
        self.maxPages = try container.decodeIfPresent(UInt.self, forKey: .maxPages) ?? nil
    }
}

// MARK: - Internal FFI conversions for SecurityLimits
internal extension SecurityLimits {
    init(_ rb: RustBridge.SecurityLimitsRef) throws {
        self.maxArchiveSize = rb.maxArchiveSize()
        self.maxCompressionRatio = rb.maxCompressionRatio()
        self.maxFilesInArchive = rb.maxFilesInArchive()
        self.maxNestingDepth = rb.maxNestingDepth()
        self.maxEntityLength = rb.maxEntityLength()
        self.maxContentSize = rb.maxContentSize()
        self.maxIterations = rb.maxIterations()
        self.maxXmlDepth = rb.maxXmlDepth()
        self.maxTableCells = rb.maxTableCells()
        self.maxPages = rb.maxPages()
    }

    func intoRust() throws -> RustBridge.SecurityLimits {
        return RustBridge.SecurityLimits(self.maxArchiveSize, self.maxCompressionRatio, self.maxFilesInArchive, self.maxNestingDepth, self.maxEntityLength, self.maxContentSize, self.maxIterations, self.maxXmlDepth, self.maxTableCells, self.maxPages)
    }
}

/// The immutable record left behind when a segment is closed.
///
/// `seal_hash` commits to every other field, including `prev_seal_hash`, so that a node's
/// seals form a hash chain of segments — the same construction as the entry chain, one
/// level up.
///
/// That back-pointer is what makes truncation detectable, and truncation is the attack the
/// segment layer would otherwise be wide open to. Without it, an attacker could delete a
/// node's oldest segment, blank the successor's `prev_seal_hash`, and present the remainder
/// as a complete history: every surviving segment verifies internally, and every link
/// between survivors holds. Suppressing the earliest records is precisely what a
/// tamper-evident log exists to prevent, so the cost — one hash input — is not worth
/// arguing about.
///
/// `entry_count` is in the preimage as a cheaper, more legible integrity signal rather than
/// as a distinct security property. `sealed_tip` already changes when entries are removed,
/// since the tip *is* the last entry's chain hash. What `entry_count` adds is an invariant a
/// store can assert at recovery — replayed entries must number exactly this many — which
/// fails with "expected 40 entries, found 37" instead of an opaque hash mismatch.
public struct SegmentSeal: Codable, Sendable, Hashable {
    public let segmentId: String
    /// The tenant this segment belongs to (S1 spec §5). Always `"default"` until the
    /// store that produced this seal is itself threaded with a real tenant context —
    /// see [`Segment::tenant_id`]'s doc comment.
    ///
    /// Defaulted on deserialize (mirroring `review::types::ReviewQueueItem::tenant_id`):
    /// a `*.seal.json` file written by any pre-S1 build has no `tenant_id` key at all, so
    /// without this, loading it back would fail outright with a missing-field error
    /// instead of defaulting to `"default"`.
    public let tenantId: String
    public let nodeId: String
    public let configHash: String
    /// Seal hash of the immediately preceding segment on this node, or `None` for the
    /// first segment. Committed into `seal_hash` so deletion of the predecessor is
    /// detectable.
    public let prevSealHash: String?
    /// Entry chain tip at seal time.
    public let sealedTip: String
    /// Number of entries in the segment at seal time.
    public let entryCount: UInt64
    /// RFC 3339 timestamp when the segment was opened.
    public let openedAt: String
    /// RFC 3339 timestamp when the segment was sealed.
    public let sealedAt: String
    /// blake3 over all other fields. Recompute with [`compute_seal_hash`] and compare to
    /// detect any post-seal modification.
    public let sealHash: String
    public init(segmentId: String, tenantId: String, nodeId: String, configHash: String, prevSealHash: String? = nil, sealedTip: String, entryCount: UInt64, openedAt: String, sealedAt: String, sealHash: String) {
        self.segmentId = segmentId
        self.tenantId = tenantId
        self.nodeId = nodeId
        self.configHash = configHash
        self.prevSealHash = prevSealHash
        self.sealedTip = sealedTip
        self.entryCount = entryCount
        self.openedAt = openedAt
        self.sealedAt = sealedAt
        self.sealHash = sealHash
    }
    private enum CodingKeys: String, CodingKey {
        case segmentId = "segment_id"
        case tenantId = "tenant_id"
        case nodeId = "node_id"
        case configHash = "config_hash"
        case prevSealHash = "prev_seal_hash"
        case sealedTip = "sealed_tip"
        case entryCount = "entry_count"
        case openedAt = "opened_at"
        case sealedAt = "sealed_at"
        case sealHash = "seal_hash"
    }
    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.segmentId = try container.decode(String.self, forKey: .segmentId)
        self.tenantId = try container.decode(String.self, forKey: .tenantId)
        self.nodeId = try container.decode(String.self, forKey: .nodeId)
        self.configHash = try container.decode(String.self, forKey: .configHash)
        self.prevSealHash = try container.decodeIfPresent(String.self, forKey: .prevSealHash) ?? nil
        self.sealedTip = try container.decode(String.self, forKey: .sealedTip)
        self.entryCount = try container.decode(UInt64.self, forKey: .entryCount)
        self.openedAt = try container.decode(String.self, forKey: .openedAt)
        self.sealedAt = try container.decode(String.self, forKey: .sealedAt)
        self.sealHash = try container.decode(String.self, forKey: .sealHash)
    }
}

