internal extension SegmentSeal {
    init(_ rb: RustBridge.SegmentSealRef) throws {
        self.segmentId = rb.segmentId().toString()
        self.tenantId = rb.tenantId().toString()
        self.nodeId = rb.nodeId().toString()
        self.configHash = rb.configHash().toString()
