        } else {
            self.elementCount = 0
        }
        if container.contains(.uniqueElements) {
            self.uniqueElements = try container.decode([String].self, forKey: .uniqueElements)
        } else {
            self.uniqueElements = []
        }
    }
}

// MARK: - Internal FFI conversions for XmlMetadata
internal extension XmlMetadata {
    init(_ rb: RustBridge.XmlMetadataRef) throws {
        self.elementCount = rb.elementCount()
