/// Policy controlling when VLM (Vision Language Model) OCR is used as a fallback.
///
/// This knob is syntactic sugar over the explicit [`OcrPipelineConfig`] stage
/// ordering. When `vlm_fallback` is set and `pipeline` is `None`, an equivalent
/// pipeline is synthesised at extraction time:
///
/// - [`VlmFallbackPolicy::Disabled`] — no synthesis; single-backend mode (default).
/// - [`VlmFallbackPolicy::OnLowQuality`] — tries the classical backend first; if the
///   result scores below `quality_threshold`, tries VLM.
/// - [`VlmFallbackPolicy::Always`] — skips the classical backend and sends every page
///   to the VLM.
///
/// When [`OcrConfig::pipeline`] is explicitly set, `vlm_fallback` is ignored — the
/// explicit pipeline takes precedence.
///
/// # Errors
///
/// Both `OnLowQuality` and `Always` require [`OcrConfig::vlm_config`] to be `Some`.
/// Constructing an [`OcrConfig`] with one of these policies but no `vlm_config` is
/// detected by `OcrConfig::validate` and will surface as a
/// `Validation` error at extraction time, not a panic.
///
/// # Example
///
/// ```rust
/// use xberg::{OcrConfig, VlmFallbackPolicy, LlmConfig};
///
/// let config = OcrConfig {
///     vlm_fallback: VlmFallbackPolicy::OnLowQuality { quality_threshold: 0.6 },
///     vlm_config: Some(LlmConfig {
///         model: "openai/gpt-4o-mini".to_string(),
///         ..Default::default()
///     }),
///     ..Default::default()
/// };
///
/// // Threshold calibration is deferred to the Stage 0 benchmark harness.
/// assert!(matches!(config.vlm_fallback, VlmFallbackPolicy::OnLowQuality { .. }));
/// ```
public enum VlmFallbackPolicy: Codable, Sendable, Hashable {
    /// No VLM fallback (default). Behaves identically to the pre-policy single-backend mode.
    case disabled
    /// Try the classical OCR backend first. If the quality score is below
    /// `quality_threshold`, send the page to the VLM.
    ///
    /// `quality_threshold` is in the `[0.0, 1.0]` range, but it is **not** the same
    /// quantity reported on `score` (GH#1584).
    /// The accept decision blends text-shape quality with confidence, weighted 0.7/0.3
    /// (`extractors::pdf::ocr::pipeline_stage_score`) -- when the backend's confidence is on
    /// a known scale it contributes only 30% of the compared score, so a page can clear this
    /// threshold on clean-looking text even while its own `PageOcrConfidence.score` reads
    /// below it. Do not calibrate this value by reading `PageOcrConfidence.score` off a
    /// sample page and expecting an equal `quality_threshold` to reproduce the same
    /// accept/reject outcome. A value of `0.5` is a reasonable starting point; calibrate with
    /// the Stage 0 benchmark harness.
    case onLowQuality(qualityThreshold: Double)
    /// Skip the classical OCR backend entirely. Every page is sent to the VLM.
    case always

    private enum CodingKeys: String, CodingKey {
        case mode = "mode"

        case qualityThreshold = "quality_threshold"    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let type = try container.decode(String.self, forKey: .mode)
        switch type {
        case "disabled":
            self = .disabled
        case "on_low_quality":
            self = .onLowQuality(qualityThreshold: try container.decode(Double.self, forKey: .qualityThreshold))
        case "always":
            self = .always
        default:
            throw DecodingError.dataCorruptedError(
                forKey: .mode,
                in: container,
                debugDescription: "Unknown VlmFallbackPolicy type: \(type)"
            )
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .disabled:
            try container.encode("disabled", forKey: .mode)
        case .onLowQuality(let qualityThreshold):
            try container.encode("on_low_quality", forKey: .mode)
            try container.encode(qualityThreshold, forKey: .qualityThreshold)

        case .always:
            try container.encode("always", forKey: .mode)
        }
    }
}
extension VlmFallbackPolicy {
    /// Returns the serde wire tag identifying this variant -- the same value
    /// the pre-promotion opaque binding's `to_string()` returned -- dropping
    /// any associated payload.
    public func toString() -> String {
        switch self {
        case .disabled:
            return "disabled"
        case .onLowQuality:
            return "on_low_quality"
        case .always:
            return "always"
        }
    }
}
extension VlmFallbackPolicy {
    func intoRust() throws -> RustBridge.VlmFallbackPolicy {
        let data = try JSONEncoder().encode(self)
        let json = String(data: data, encoding: .utf8) ?? "null"
        return try RustBridge.vlmFallbackPolicyFromJson(json)
    }
}

/// PII categories the pattern engine recognises.
public enum XbergPiiCategory: Codable, Sendable, Hashable {
    /// Email address (e.g. `user@example.com`).
    case email
    /// Phone number in any common format.
    case phone
    /// US Social Security Number.
    case ssn
    /// Payment card number (Visa, Mastercard, Amex, etc.).
    case creditCard
    /// Postal / ZIP code.
    case postalCode
    /// IPv4 or IPv6 address.
    case ipAddress
    /// International Bank Account Number.
    case iban
    /// SWIFT / BIC bank identifier code.
    case swiftBic
    /// Date of birth.
    case dateOfBirth
    /// Person name, surfaced by the optional NER backend.
    case person
    /// Organization name, surfaced by the optional NER backend.
    case organization
    /// Location, surfaced by the optional NER backend.
    case location
    /// Caller-supplied custom category (e.g. internal employee IDs).
    ///
    /// Surfaced by the redaction engine when a hit comes from
    /// [`RedactionConfig::custom_terms`](crate::core::config::redaction::RedactionConfig::custom_terms)
    /// or [`RedactionConfig::custom_patterns`](crate::core::config::redaction::RedactionConfig::custom_patterns).
    /// The string is the label passed alongside the term/pattern. Use those
    /// fields rather than constructing `Custom` directly via the
    /// `categories` filter — the pattern engine cannot detect arbitrary text
    /// from a category name alone.
    case custom(field0: String)

    fileprivate struct __AlefExternalTagKey: CodingKey {
        let stringValue: String
        var intValue: Int? { nil }
        init(_ stringValue: String) { self.stringValue = stringValue }
        init?(stringValue: String) { self.init(stringValue) }
        init?(intValue: Int) { nil }
    }

    public init(from decoder: Decoder) throws {
        if let single = try? decoder.singleValueContainer(), let raw = try? single.decode(String.self) {
            switch raw {
            case "email":
                self = .email
                return
            case "phone":
                self = .phone
                return
            case "ssn":
                self = .ssn
                return
            case "credit_card":
                self = .creditCard
                return
            case "postal_code":
                self = .postalCode
                return
            case "ip_address":
                self = .ipAddress
                return
            case "iban":
                self = .iban
                return
            case "swift_bic":
                self = .swiftBic
                return
            case "date_of_birth":
                self = .dateOfBirth
                return
            case "person":
                self = .person
                return
            case "organization":
                self = .organization
                return
            case "location":
                self = .location
                return
            default:
                throw DecodingError.dataCorrupted(
                    .init(codingPath: decoder.codingPath, debugDescription: "unknown variant tag \(raw)"))
            }
        }
        let container = try decoder.container(keyedBy: __AlefExternalTagKey.self)
        guard container.allKeys.count == 1, let key = container.allKeys.first else {
            throw DecodingError.dataCorrupted(
                .init(codingPath: decoder.codingPath, debugDescription: "expected exactly one variant key"))
        }
        switch key.stringValue {
        case "custom":
            self = .custom(field0: try container.decode(String.self, forKey: key))
        default:
            throw DecodingError.dataCorrupted(
                .init(codingPath: decoder.codingPath, debugDescription: "unknown variant key \(key.stringValue)"))
        }
    }

    public func encode(to encoder: Encoder) throws {
        switch self {
        case .email:
            var single = encoder.singleValueContainer()
            try single.encode("email")
        case .phone:
            var single = encoder.singleValueContainer()
            try single.encode("phone")
        case .ssn:
            var single = encoder.singleValueContainer()
            try single.encode("ssn")
        case .creditCard:
            var single = encoder.singleValueContainer()
            try single.encode("credit_card")
        case .postalCode:
            var single = encoder.singleValueContainer()
            try single.encode("postal_code")
        case .ipAddress:
            var single = encoder.singleValueContainer()
            try single.encode("ip_address")
        case .iban:
            var single = encoder.singleValueContainer()
            try single.encode("iban")
        case .swiftBic:
            var single = encoder.singleValueContainer()
            try single.encode("swift_bic")
        case .dateOfBirth:
            var single = encoder.singleValueContainer()
            try single.encode("date_of_birth")
        case .person:
            var single = encoder.singleValueContainer()
            try single.encode("person")
        case .organization:
            var single = encoder.singleValueContainer()
            try single.encode("organization")
        case .location:
            var single = encoder.singleValueContainer()
            try single.encode("location")
        case .custom(let value):
            var container = encoder.container(keyedBy: __AlefExternalTagKey.self)
            try container.encode(value, forKey: __AlefExternalTagKey("custom"))
        }
    }
}
