/// Errors returned by `JobStore` implementations.
///
/// Variants carry the job id where applicable so callers can log a useful
/// message without re-fetching the job.
public enum JobError: Swift.Error {
    /// No job with the given id exists in the store.
    case notFound(message: String, field0: String)
    /// A `transition` call failed because the job's current status was not the
    /// expected `from` value. This is the normal outcome for the losing worker in a
    /// two-worker race; callers should treat it as a signal to back off, not a bug.
    case statusMismatch(message: String, id: String, expected: JobStatus, actual: JobStatus)
    /// A transition that would re-queue a terminal job was refused by the API's
    /// conservative retry policy. Retry is intentionally disabled: re-ingest would
    /// need the original source reference plus tenant/principal binding and an
    /// idempotency key, none of which the job record is allowed to persist.
    case retryDisabled(message: String, id: String)
    /// The backend does not implement the optional `delete`
    /// seam, so a retention policy cannot reclaim its expired rows. Callers may
    /// treat this as a warning; it never makes the job itself unreadable.
    case deleteUnsupported(message: String, field0: String)
    /// An internal store error (e.g. lock poisoning) that cannot be recovered by the
    /// caller. Should not occur under normal operation.
    case `internal`(message: String, field0: String)
    /// Synthetic case raised when a Rust serde unit-enum raw value cannot
    /// be mapped to a known Swift case during DTO unmarshaling.
    case validation(message: String, source: String)
}
extension JobError: Swift.CustomStringConvertible {
    /// Uses the Rust display template when available, otherwise the transported message or variant name.
    public var description: String {
        switch self {
        case .notFound(message: let message, field0: _): return message
        case .statusMismatch(message: let message, id: _, expected: _, actual: _): return message
        case .retryDisabled(message: let message, id: _): return message
        case .deleteUnsupported(message: let message, field0: _): return message
        case .`internal`(message: let message, field0: _): return message
        case .validation(message: let message, source: _): return message
        }
    }
}

