/// Errors returned by `TenantStore` implementations.
public enum TenantError: Swift.Error {
    /// `create` was called with an id that already has a row.
    ///
    /// Not a race-tolerant compare-and-swap error like `
    /// StatusMismatch` — tenant admission is rare, operator-driven, and idempotent
    /// re-admission (spec §8's migration) is the caller's job to detect via `get`
    /// first, not this store's to silently allow. Silently allowing it would let a
    /// second `create("acme", ...)` with a different `display_name` overwrite the
    /// first without the caller ever deciding that was intended.
    case alreadyExists(message: String, field0: TenantId)
    /// No tenant with the given id exists in the store.
    case notFound(message: String, field0: TenantId)
    /// An internal store error (e.g. lock poisoning) that cannot be recovered by the
    /// caller. Should not occur under normal operation.
    case `internal`(message: String, field0: String)
    /// Synthetic case raised when a Rust serde unit-enum raw value cannot
    /// be mapped to a known Swift case during DTO unmarshaling.
    case validation(message: String, source: String)
}
extension TenantError: Swift.CustomStringConvertible {
    /// Uses the Rust display template when available, otherwise the transported message or variant name.
    public var description: String {
        switch self {
        case .alreadyExists(message: let message, field0: _): return message
        case .notFound(message: let message, field0: _): return message
        case .`internal`(message: let message, field0: _): return message
        case .validation(message: let message, source: _): return message
        }
    }
}

extension JobError {
    init?(bridgeError error: RustBridge.AlefBridgeError) {
        let message = error.message().toString()
        let status = error.status()
        let retryAfterMs = error.retryAfterMs()
        _ = (message, status, retryAfterMs)
        do {
            switch error.kind().toString() {
            case "NotFound":
                self = .notFound(message: message, field0: try alefBridgeErrorField(error, "_0", as: (String).self))
            case "RetryDisabled":
                self = .retryDisabled(message: message, id: try alefBridgeErrorField(error, "id", as: (String).self))
            case "DeleteUnsupported":
                self = .deleteUnsupported(message: message, field0: try alefBridgeErrorField(error, "_0", as: (String).self))
            case "Internal":
                self = .`internal`(message: message, field0: try alefBridgeErrorField(error, "_0", as: (String).self))
            default:
                return nil
            }
        } catch {
            return nil
        }
    }

    public var kind: String {
        switch self {
        case .notFound: return "NotFound"
        case .statusMismatch: return "StatusMismatch"
        case .retryDisabled: return "RetryDisabled"
        case .deleteUnsupported: return "DeleteUnsupported"
        case .`internal`: return "Internal"
        case .validation: return "Validation"
        }
    }
}

