        let _rb_seals: RustVec<RustString> = try ({ () throws -> RustVec<RustString> in let v = RustVec<RustString>(); for item in seals { let data = try JSONEncoder().encode(item); let json = String(data: data, encoding: .utf8) ?? "null"; v.push(value: RustString(json)) }; return v }())
    return try alefBridgedCall { try RustBridge.verifySealChain(_rb_seals) }
}
